const AUTHORING_FLOW_NOTE =
  " Custom drafting: use relevant kit_authoring_guide sections and per-app kit_vocabulary; reuse unchanged help. Validate the exact publish body. Publish private, kit_install, then prove a run or Action tool call before later public promotion. Check key_info; never automatically retry a 403.";

